import{_ as o,l as s,o as e,c as l,v as t,p,x as r,d as n,i as d,S as A}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"证书与 PKI","description":"","frontmatter":{"title":"证书与 PKI","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cert-pki.md","filePath":"cs/cert-pki.md","lastUpdated":1789023840000}'),E={name:"cs/cert-pki.md"};function c(h,a,_,m,P,C){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="证书与-pki" tabindex="-1">证书与 PKI <a class="header-anchor" href="#证书与-pki" aria-label="Permalink to &quot;证书与 PKI&quot;">​</a></h1><div class="epigraph"><p>证书把公钥绑到名字，并用另一把私钥签名；信任是对签发者的，不是对那串比特本身的神秘属性。</p><footer>—— 据 RFC 5280（X.509）；Anderson 对 PKI 失败模式的整理</footer></div><p><a href="/cs/mac-signature">上一课</a>给出可公开验证的签名。本课不重写验签算法。缺口是：对方递来的公钥为什么是「银行」而不是中间人。<a href="/cs/mac-signature">TLS 入口</a>已经假定证书存在；这里把 PKI 收成：根锚、链、撤销，以及信任锚本身是配置不是协议推出来的。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>信封和签名都要 \\(pk\\)。若 \\(pk\\) 来自刚连上的对端，威胁模型里的主动者可以换钥匙。缺口不是新的公钥算法，而是<strong>绑定</strong>：证书 = 名字 + 公钥 + 元数据，由 CA 的私钥签名。验证者预置根证书，沿链验到叶子。名字还要与用户意图（主机名）一致，否则链再真也绑错对象。</p><p><span class="marginnote">浏览器根程序决定锚。CA 被骗或被强制签发，链仍然密码学合法——PKI 的完整性依赖 CA 与撤销，不单依赖签名方案。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>X.509 链：叶子由中间签，中间由根签。验证：路径、有效期、密钥用法、主机名（SAN）。撤销：CRL 或 OCSP，失败策略决定可用性与安全的挤法。本课不把 CT 日志的全部生态写完，只承认：仅验链不够应对误签，透明日志是补丁。</p>',8)),(e(),p(A,null,{default:r(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E9%A2%84%E7%BD%AE%E6%A0%B9%E9%94%9A%22%5D%20--%3E%20CHAIN%5B%22%E9%AA%8C%E8%AF%81%E4%B9%A6%E9%93%BE%22%5D%0A%20%20CHAIN%20--%3E%20NAME%5B%22%E5%90%8D%E5%AD%97%E5%8C%B9%E9%85%8D%22%5D%0A%20%20NAME%20--%3E%20SESS%5B%22%E5%90%8E%E8%AF%BE%E4%BC%9A%E8%AF%9D%20%2F%20%E5%8F%A3%E4%BB%A4%22%5D%0A%20%20CHAIN%20--%3E%20PWD%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%8F%A3%E4%BB%A4%E4%B8%8E%E5%8A%A0%E7%9B%90%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>PKI 把「谁的公钥」从每次人工比对指纹，变成对少数锚的信任。这服务 TLS 握手里的服务器认证；客户端证书较少见，机制相同。与<a href="/cs/two-pc">两阶段提交</a>对照：2PC 假设参与者身份已定；PKI 要在开放网络上建立身份。锚泄露或算法过时，要轮换根——那是运维，不是握手能单独修的。</p><p>主机名检查发生在链验证之后：链真而名字错，仍是中间人几何。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 DANE/DNSSEC 与 Web PKI 混成一课。也不把「自签证书」当成 PKI 失败：它只是把锚放到对端自己，适合已有带外信任。本课不讲区块链替代 CA。</p><p>叶子密钥轮换要发新证书；锚轮换要更新每个验证者的预置，周期长得多。后课默认：开放网上的公钥来自证书链与名字检查；人的口令是另一条身份路径，要单独存储与盐。</p><p>时间错误会让有效证书被拒、过期证书被收。可用与完整在时钟上相遇，本课只要求验证包含有效期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>链上的每一个签名都要验；跳过中间用途检查等于换锚。</p></li><li><p>后课口令是人的秘密路径，与机器证书并列，不互相替代。</p></li><li><p>签名可验；本课把公钥绑到名字，信任落在根锚与 CA。</p></li><li><p>链合法 ≠ 名字对、≠ CA 没被骗。</p></li><li><p>人记得的秘密如何存，是口令课缺口。</p></li><li><p>出处：RFC 5280；Anderson, <em>Security Engineering</em>；对照 RFC 8446 对证书的使用。</p></li></ul>',9))])}const B=o(E,[["render",c]]);export{f as __pageData,B as default};
